import{_ as a,o as s,c as i,a2 as n}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"前端工程化地图","description":"从本地开发到持续交付，理解每一层工具解决的实际问题，并按团队需要选择。","frontmatter":{"title":"前端工程化地图","description":"从本地开发到持续交付，理解每一层工具解决的实际问题，并按团队需要选择。"},"headers":[],"relativePath":"engineering/toolchain.md","filePath":"engineering/toolchain.md","lastUpdated":1786262003000}'),e={name:"engineering/toolchain.md"};function d(l,t,h,p,r,o){return s(),i("div",null,[...t[0]||(t[0]=[n(`<h1 id="前端工程化地图" tabindex="-1">前端工程化地图 <a class="header-anchor" href="#前端工程化地图" aria-label="Permalink to &quot;前端工程化地图&quot;">​</a></h1><p>“最新技术”不是工具清单。工程化真正要解决的是：让多人在相同规则下开发、验证、交付，并能在问题出现时快速定位。先建立流程地图，再讨论具体工具。</p><h2 id="一条可维护的交付链路" tabindex="-1">一条可维护的交付链路 <a class="header-anchor" href="#一条可维护的交付链路" aria-label="Permalink to &quot;一条可维护的交付链路&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>需求与设计</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>本地开发 → 静态检查 → 自动化测试 → 构建产物 → 预览/发布 → 监控与复盘</span></span></code></pre></div><p>每一层都应有明确的输入、输出和失败信号。工具只是一种实现方式，流程缺口不能靠多装几个插件填补。</p><h2 id="六个常见层次" tabindex="-1">六个常见层次 <a class="header-anchor" href="#六个常见层次" aria-label="Permalink to &quot;六个常见层次&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层次</th><th>要回答的问题</th><th>典型能力</th></tr></thead><tbody><tr><td>包管理</td><td>依赖是否可复现？</td><td>锁文件、依赖审计、脚本入口</td></tr><tr><td>开发服务</td><td>修改能否快速反馈？</td><td>热更新、环境变量、本地代理</td></tr><tr><td>代码质量</td><td>问题能否在提交前发现？</td><td>格式化、Lint、类型检查</td></tr><tr><td>测试</td><td>行为能否被重复验证？</td><td>单元、组件、端到端测试</td></tr><tr><td>构建发布</td><td>产物是否一致可追溯？</td><td>压缩、分包、版本、CI</td></tr><tr><td>运行观察</td><td>上线后能否发现并复现问题？</td><td>错误采集、性能指标、日志关联</td></tr></tbody></table><h2 id="选择工具的四个问题" tabindex="-1">选择工具的四个问题 <a class="header-anchor" href="#选择工具的四个问题" aria-label="Permalink to &quot;选择工具的四个问题&quot;">​</a></h2><ol><li>项目已有脚手架能否满足需求？优先利用既有约定，减少同类工具并存。</li><li>团队是否能维护它？配置复杂度、升级成本和排错能力都算成本。</li><li>它是否解决了当前可观察的问题？“其他项目在用”不是充分理由。</li><li>失败时能给出有用信息吗？一个可读的错误提示比一套黑盒自动化更重要。</li></ol><h2 id="一个最小可行的项目约定" tabindex="-1">一个最小可行的项目约定 <a class="header-anchor" href="#一个最小可行的项目约定" aria-label="Permalink to &quot;一个最小可行的项目约定&quot;">​</a></h2><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;scripts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;dev&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;启动本地开发服务&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;lint&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;检查代码规范&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;test&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;运行自动化测试&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;build&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;生成可部署产物&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>无论框架如何变化，团队只要能通过统一脚本完成这四件事，新成员就不必先记忆每个工具的细节。CI 应调用同一组脚本，而不是维护一份只在服务器上存在的构建逻辑。</p><h2 id="何时该增加一项能力" tabindex="-1">何时该增加一项能力 <a class="header-anchor" href="#何时该增加一项能力" aria-label="Permalink to &quot;何时该增加一项能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>信号</th><th>合理的改进</th></tr></thead><tbody><tr><td>同类格式问题反复出现在评审中</td><td>引入格式化或静态检查，并接入提交前/CI</td></tr><tr><td>修复后经常出现回归</td><td>为关键行为补最小自动化测试</td></tr><tr><td>发布依赖某个人的本地环境</td><td>将构建和部署步骤写入可重复的工作流</td></tr><tr><td>线上错误只能靠用户描述猜测</td><td>增加脱敏的错误与性能观察能力</td></tr></tbody></table><p>工程化是持续减小不确定性的过程。每次只补一个真实痛点，并记录为什么引入、由谁维护、何时可以移除，工具链才不会失控。</p>`,15)])])}const E=a(e,[["render",d]]);export{c as __pageData,E as default};
